import{_ as o,o as a,c as n,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const r="/images/admin/zonas-envio.webp",g=JSON.parse('{"title":"7. Configurar Costos de Envío y Crear Cupones","description":"","frontmatter":{},"headers":[],"relativePath":"admin/configuracion.md","filePath":"admin/configuracion.md"}'),t={name:"admin/configuracion.md"};function i(c,e,d,l,u,p){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_7-configurar-costos-de-envio-y-crear-cupones" tabindex="-1">7. Configurar Costos de Envío y Crear Cupones <a class="header-anchor" href="#_7-configurar-costos-de-envio-y-crear-cupones" aria-label="Permalink to &quot;7. Configurar Costos de Envío y Crear Cupones&quot;">​</a></h1><p>En el módulo de <strong>Configuración</strong> puedes ajustar las tarifas que se cobran a los clientes según la provincia donde vivan y crear promociones con cupones de descuento.</p><hr><h2 id="_7-1-zonas-y-costos-de-envio-en-panama" tabindex="-1">7.1 Zonas y Costos de Envío en Panamá <a class="header-anchor" href="#_7-1-zonas-y-costos-de-envio-en-panama" aria-label="Permalink to &quot;7.1 Zonas y Costos de Envío en Panamá&quot;">​</a></h2><p>Para fijar cuánto cuesta enviar a cada provincia entra a <a href="https://pyme.rsfsecure.site/admin/zonas" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/zonas</a>:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Configuración de Tarifas de Envío por Provincia</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/zonas</span></div><div class="screenshot-body"><img src="'+r+'" alt="Configuración de Tarifas de Envío por Provincia" loading="lazy" decoding="async"></div></div><h3 id="como-configurar-los-envios" tabindex="-1">Cómo configurar los envíos: <a class="header-anchor" href="#como-configurar-los-envios" aria-label="Permalink to &quot;Cómo configurar los envíos:&quot;">​</a></h3><ol><li><strong>Tarifa Base:</strong> El costo normal para un paquete estándar (ejemplo: <code>$3.50</code> en Ciudad de Panamá, <code>$5.00</code> en Panamá Oeste, <code>$7.00</code> en el Interior).</li><li><strong>Promoción de Envío Gratis:</strong> Puedes definir que si el cliente compra más de cierto monto (por ejemplo: <code>$75.00</code>), el envío le salga completamente gratis. El sistema aplicará la promoción automáticamente en el carrito.</li></ol><hr><h2 id="_7-2-como-crear-un-cupon-de-descuento" tabindex="-1">7.2 Cómo Crear un Cupón de Descuento <a class="header-anchor" href="#_7-2-como-crear-un-cupon-de-descuento" aria-label="Permalink to &quot;7.2 Cómo Crear un Cupón de Descuento&quot;">​</a></h2><p>Para crear promociones entra a <a href="https://pyme.rsfsecure.site/admin/cupones" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/cupones</a>:</p><ol><li>Pulsa en <strong>&quot;+ Crear Cupón&quot;</strong>.</li><li><strong>Código del Cupón:</strong> Escribe la palabra que usarán los clientes (ej. <code>MAMA2026</code>, <code>BLACKFRIDAY</code> o <code>BIENVENIDA</code>).</li><li><strong>Tipo de Descuento:</strong></li></ol><ul><li><strong>Porcentaje:</strong> Por ejemplo, un <code>10%</code> o <code>15%</code> de descuento sobre el total de la compra.</li><li><strong>Monto Fijo:</strong> Por ejemplo, <code>$5.00</code> o <code>$10.00</code> de descuento directo.</li></ul><ol start="4"><li><strong>Reglas del Cupón:</strong></li></ol><ul><li>Puedes poner un monto mínimo de compra (ej. solo aplica si compran más de <code>$30.00</code>).</li><li>Puedes poner un límite de usos (ej. válido solo para los primeros 50 clientes).</li><li>Puedes poner fecha de expiración (ej. vence este domingo a medianoche).</li></ul><ol start="5"><li>Haz clic en <strong>&quot;Guardar Cupón&quot;</strong>. Ya puedes compartirlo en tus redes sociales o WhatsApp para que tus clientes lo aprovechen.</li></ol>',16)])])}const h=o(t,[["render",i]]);export{g as __pageData,h as default};
